import re
import os
from pathlib import Path


PROFILES_PATH = Path(os.path.abspath(__file__)).parents[2] / "auto_config" / "config" / "profiles"
available_profiles = os.listdir(PROFILES_PATH)


def get_profile_names(pattern=''):
    return sorted([profile for profile in available_profiles if re.search(pattern, profile)])


if __name__ == '__main__':
    print(get_profile_names('R4A_CUS'))
